style.css:
@-moz-document domain("dashboard.goswift.ly") {
.component-module-panel>.floating-panel {
    background-color: #EEF2F4;
  }

  .component-module-panel>.floating-panel>.divider {
    display: none;
  }

  .component-module-panel>.floating-panel>.swiftly-logo>.label,
  .component-module-panel>.floating-panel>.agency>.change-agency-overlay,
  .component-item>a>.label,
  .component-module-panel>.floating-panel>.agency>.label {
    color: #607686;
  }

  .component-item {
    margin-bottom: 10px;
    transition: none;
  }

  .component-item>a>.icon-wrapper svg {
    fill: #607686;
  }

  .component-item.selected>a>.icon-wrapper svg {
    fill: #0C66D4;
  }

  .component-item.selected>a>.label {
    color: #0C66D4;
  }

  .component-item:hover:not(.selected) {
    background-color: transparent;
  }

  .component-item.selected {
    background-color: transparent;
    font-weight: bold;
  }

  .component-item.selected>a:before {
    display: block;
    position: absolute;
    top: 0;
    left: 8px;
    width: auto;
    right: 8px;
    height: 40px;
    border-radius: 4px;
    background-color: #C5E3FC;
    content: ' ';
  }

  .component-item:hover:not(.selected)>a:before {
    display: block;
    position: absolute;
    top: 0;
    left: 8px;
    width: auto;
    right: 8px;
    height: 40px;
    border-radius: 4px;
    background-color: white;
    content: ' ';
  }

  .component-module-panel>.floating-panel>.swiftly-logo>.label {
    font-size: 18px;
    color: #10252F;
  }

  .component-module-panel>.floating-panel {
    overflow: hidden;
    transition: none;
  }

  .component-module-panel>.floating-panel.expanded {
    transition: none;
  }

  .component-module-panel>.floating-panel>.swiftly-logo {
    height: 67px;
  }

  .component-item>a>.label,
  .component-module-panel>.floating-panel>.swiftly-logo>.label {
    left: 56px;
  }

  .component-module-panel>.floating-panel>.agency>.change-agency-overlay {
    text-indent: 56px;
  }

  .component-module-panel>.floating-panel>.agency>.label {
    left: 13px;
  }
}
